import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        assertArrayEquals(new long[]{0, 0, 0, 1}, Solution.summarize(new int[0][]));
        assertArrayEquals(new long[]{2, 3, 6666, 1}, Solution.summarize(
                new int[][]{{1, 2}, {1, 1}}));
        assertArrayEquals(new long[]{74, 150, 4933, 0}, Solution.summarize(
                new int[][]{{50, 100}, {24, 50}}));
        assertArrayEquals(new long[]{0, 1, 0, 0}, Solution.summarize(
                new int[][]{{0, 1}}));
        assertArrayEquals(new long[]{4294967294L, 4294967294L, 10000, 1}, Solution.summarize(
                new int[][]{{Integer.MAX_VALUE, Integer.MAX_VALUE},
                            {Integer.MAX_VALUE, Integer.MAX_VALUE}}));

        int[][] input = {{7, 10}, {5, 10}};
        int[][] snapshot = deepCopy(input);
        long[] result = Solution.summarize(input);
        assertDeepEquals(snapshot, input, "input was mutated");
        input[0][0] = 0;
        input[1] = new int[]{10, 10};
        assertArrayEquals(new long[]{12, 20, 6000, 1}, result);

        expect(NullPointerException.class, () -> Solution.summarize(null));
        expect(NullPointerException.class, () -> Solution.summarize(new int[][]{null}));
        expect(IllegalArgumentException.class, () -> Solution.summarize(new int[][]{{1}}));
        expect(IllegalArgumentException.class, () -> Solution.summarize(new int[][]{{1, 2, 3}}));
        expect(IllegalArgumentException.class, () -> Solution.summarize(new int[][]{{0, 0}}));
        expect(IllegalArgumentException.class, () -> Solution.summarize(new int[][]{{0, -1}}));
        expect(IllegalArgumentException.class, () -> Solution.summarize(new int[][]{{-1, 10}}));
        expect(IllegalArgumentException.class, () -> Solution.summarize(new int[][]{{11, 10}}));
    }

    private static int[][] deepCopy(int[][] source) {
        int[][] copy = new int[source.length][];
        for (int i = 0; i < source.length; i++) copy[i] = source[i].clone();
        return copy;
    }

    private static void assertDeepEquals(int[][] expected, int[][] actual, String message) {
        if (!Arrays.deepEquals(expected, actual)) throw new AssertionError(message);
    }

    private static void assertArrayEquals(long[] expected, long[] actual) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError("expected " + Arrays.toString(expected) + " but got " + Arrays.toString(actual));
        }
    }

    private static void expect(Class<? extends Throwable> type, Action action) {
        try {
            action.run();
        } catch (Throwable thrown) {
            if (type.isInstance(thrown)) return;
            throw new AssertionError("expected " + type.getName() + " but got " + thrown, thrown);
        }
        throw new AssertionError("expected " + type.getName());
    }

    private interface Action { void run(); }
}

